import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Checkbox.stories";
import Checkbox from ".";

const { Basic } = composeStories(stories) as any;

describe("Checkbox component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("should get checked when clicking on label", () => {
    render(<Checkbox label="checkbox" />);
    fireEvent.click(screen.getByText("checkbox"));
    expect(screen.getByRole("checkbox")).toBeChecked();
  });

  it("should get checked when clicking on checkbox", () => {
    render(<Checkbox label="checkbox" />);
    fireEvent.click(screen.getByRole("checkbox"));
    expect(screen.getByRole("checkbox")).toBeChecked();
  });

  it("passes through props to the input element", () => {
    render(<Checkbox data-testid="checkbox" />);
    expect(screen.queryByRole("checkbox")).toHaveAttribute("data-testid", "checkbox");
  });

  it("dispatch event and value", () => {
    const onChange = jest.fn();
    render(<Checkbox onChange={onChange} />);
    const input = screen.getByRole("checkbox");
    fireEvent.click(input);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(expect.anything(), true);
    fireEvent.click(input);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith(expect.anything(), false);
  });

  it("allow forwardRef", () => {
    const CheckboxWithRef = () => {
      const inputRef = React.useRef<HTMLInputElement>(null);
      React.useEffect(() => {
        inputRef.current && inputRef.current.focus();
      }, []);
      return <Checkbox ref={inputRef} />;
    };

    render(<CheckboxWithRef />);
    expect(screen.getByRole("checkbox")).toHaveFocus();
  });
});
